/*
 * A007346  Order of group generated by perfect shuffles of 2n cards.
 * https://oeis.org/A007346
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, nice, easy
 * Formula:   not stated
 * Range:     u8 n <= 4, u16 n <= 6, u32 n <= 10, u64 n <= 16, u128 n <= 28,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Formula (Diaconis-Graham-Kantor, see Maple program):
   n = 2^k: a(n) = 2^(k+1)*(k+1);  n = 6: a(n) = 2^6*120;  n = 12: a(n) = 2^11*95040;
   otherwise n mod 4 = 0: a(n) = 2^(n-2)*n!;  n mod 4 = 1 or 3: a(n) = 2^(n-1)*n!;
   n mod 4 = 2: a(n) = 2^n*n! */
seq_t a(idx_t n) {
    if ((n & (n - 1)) == 0) {
        idx_t k = 0;
        while (((idx_t)1 << k) < n) k++;
        seq_t r = (seq_t)(k + 1);
        for (idx_t i = 0; i <= k; i++) r *= 2;
        return r;
    }
    if (n == 6) return (seq_t)64 * 120;
    if (n == 12) return (seq_t)2048 * 95040;
    idx_t e;
    switch (n % 4) {
        case 0: e = n - 2; break;
        case 2: e = n; break;
        default: e = n - 1; break;
    }
    seq_t r = 1;
    for (idx_t i = 2; i <= n; i++) r *= (seq_t)i;
    for (idx_t i = 0; i < e; i++) r *= 2;
    return r;
}
